import{_ as t,o,c as r,j as a,a as P}from"./chunks/framework.QCr1ZR1X.js";const m=JSON.parse('{"title":"思维导图-第6章-工业互联网APP","description":"","frontmatter":{},"headers":[],"relativePath":"mindmap/思维导图-第6章-工业互联网APP.md","filePath":"mindmap/思维导图-第6章-工业互联网APP.md","lastUpdated":1786967935000}'),s={name:"mindmap/思维导图-第6章-工业互联网APP.md"};function d(n,e,i,p,c,A){return o(),r("div",null,[...e[0]||(e[0]=[a("h1",{id:"思维导图-第6章-工业互联网app",tabindex:"-1"},[P("思维导图-第6章-工业互联网APP "),a("a",{class:"header-anchor",href:"#思维导图-第6章-工业互联网app","aria-label":'Permalink to "思维导图-第6章-工业互联网APP"'},"​")],-1),a("div",{class:"mermaid"},'# 第6章 工业互联网APP — 思维导图 ## 6.1 两种APP，同一个逻辑 - 消费APP类比：手机APP下载即用 - 工业APP类比：工业互联网平台上下载即用 ## 6.2 工业APP：小而精的工业软件 ### 工业APP定义 - AII《工业APP白皮书》 - 基于工业互联网平台开发 - 面向特定工业场景 - 解决特定工业问题 - 轻量化应用 ### 工业APP vs 传统工业软件 - 小而精 vs 大而全 - 部署周期：天/小时 vs 月/年 - 低代码/无代码 vs 专业开发团队 - 持续迭代 vs 半年到一年大版本 ### 五类工业APP - 设备监控类：实时显示运行状态 - 分析诊断类：历史数据统计分析 - 预测预警类：预判未来状态，触发告警 - 操作辅助类：标准化作业指导（SOP） - 管理决策类：汇总关键经营指标 ## 6.3 低代码：用积木搭应用 ### 低代码概念 - 80%常见需求：拖拽积木完成 - 20%特殊逻辑：手写代码 - 不排斥写代码，只是降低"从零写代码"的比例 ### 公民开发者（Citizen Developer） - Gartner提出 - 业务人员使用低代码工具搭建应用 - 预测到2026年：大型企业中公民开发者数量是专业开发者的4倍 ## 6.4 动手实践：Dashboard节点逐一上手 ### 安装Dashboard插件 - node-red-dashboard 或 @flowfuse/node-red-dashboard ### 六种Dashboard节点 - Gauge（仪表盘） - 支持颜色分段（绿/黄/红） - Chart（折线图/柱状图） - 支持多topic多线 - Button（按钮） - 点击触发事件 - Text（文本显示） - 支持模板变量{{msg.payload}} - Notification（通知弹窗） - 支持info/warn/error级别 - LED（指示灯） - 红/黄/绿三色 ### Dashboard三级布局系统 - Tab（标签页） → Group（分组卡片） → Widget（部件节点） ## 6.5 综合实践：开发产线设备监控Dashboard ### 实践任务 - 创建布局 - 1个Tab + 4个Group - 搭建仪表盘 - 温度Gauge（颜色分段：绿0-60/黄60-80/红80-100） - 振动Gauge（颜色分段） - 搭建趋势图 - 温度&振动双线Chart（通过topic区分） - 搭建指示灯和文本显示 - LED指示灯（正常/异常） - Text文本显示（设备状态） - Button按钮（触发动作） - Notification告警通知 - 整体联调 - Inject → 传感器模拟 → Change提取 → Gauge/LED/Chart/Text/Button/Notification ### 工业APP安全四要素 - 访问控制 - 数据加密（HTTPS） - 权限管理 - 日志审计 ## 🎯 课程思政 - 每一个像素都关乎安全——工业APP中的工匠精神 - 消费APP出错：最多退回上一页 - 工业APP出错：可导致产线停机甚至安全事故 - 1979年三里岛核事故：操作界面设计不当是重要原因 - 化工厂紧急停车按钮：红色醒目、拍下即触发 - 报警信息必须红色闪烁',-1)])])}const l=t(s,[["render",d]]);export{m as __pageData,l as default};
